// ── XOR Tricks ────────────────────────────────────────────────

// 1. Find the unique element — every other appears exactly twice
function findUnique(arr) {
  return arr.reduce((acc, x) => acc ^ x, 0);
}
console.log(findUnique([2, 3, 4, 3, 2])); // 4
// Trace: 0^2=2, 2^3=1, 1^4=5, 5^3=6, 6^2=4
// Group view: (2^2)^(3^3)^4 = 0^0^4 = 4

// 2. XOR swap — swap without a temporary variable
let x = 13, y = 27;
console.log(`before: x=${x}, y=${y}`);
x ^= y;  // x = 13^27 = 22
y ^= x;  // y = 27^22 = 13 (= original x)
x ^= y;  // x = 22^13 = 27 (= original y)
console.log(`after:  x=${x}, y=${y}`); // x=27, y=13

// 3. Hamming distance — count bit positions where a and b differ
function hammingDistance(a, b) {
  let diff = a ^ b; // 1-bits mark positions where a and b differ
  let count = 0;
  while (diff > 0) {
    diff &= (diff - 1); // clear lowest set bit (Kernighan)
    count++;
  }
  return count;
}
console.log(hammingDistance(9, 14));
// 9  = 1001, 14 = 1110, XOR = 0111, popcount = 3

// 4. Count Set Bits — Brian Kernighan's algorithm
function popcount(n) {
  let count = 0;
  while (n > 0) {
    n &= (n - 1); // clear the lowest set bit each iteration
    count++;
  }
  return count;
}
console.log(popcount(0b101100)); // 3 (bits at positions 2,3,5)
console.log(popcount(0xFF));     // 8 (all bits set in a byte)

// 5. Power of 2 check
const isPow2 = n => n > 0 && (n & (n - 1)) === 0;
console.log(isPow2(16)); // true   (0b10000 & 0b01111 = 0)
console.log(isPow2(12)); // false  (0b1100 & 0b1011 = 0b1000 != 0)

sections.content:
When a set has at most 20–25 elements, it is common in competitive programming and dynamic programming to represent the set as a bitmask — an integer where bit k is set if and only if element k is in the set. Subset enumeration then becomes a bit-manipulation problem.

**Enumerate all 2^n subsets of an n-element universe** in order from 0 to 2^n - 1: a simple loop from 0 to `(1 << n) - 1` works — each integer naturally represents a unique subset via its bit pattern.

**Enumerate all subsets of a specific mask**: This is trickier and more powerful. Given a mask `s`, you want to visit every submask — every subset of the bits set in `s`. The idiom:

```javascript
for (let sub = s; sub > 0; sub = (sub - 1) & s) {
  // process submask 'sub'
}
// don't forget to process sub = 0 (empty set) separately
```

Why does this work? Starting at `s` itself, each iteration computes the next-smaller submask by: decrement `sub` by 1 (which flips the lowest 1-bit of `sub` to 0 and sets all lower bits), then AND with `s` (which zeroes out any bits that were not in `s` to begin with). The result is the largest submask that is strictly smaller than the current one. The loop terminates when `sub` reaches 0.

The total number of iterations across all 2^n masks equals exactly **3^n** (each element is independently 'in the outer mask but not the sub-mask', 'in both', or 'in neither'). This bound is crucial for complexity analysis of bitmask DP.

**Bitmask dynamic programming** uses this to solve exponential-size problems in O(3^n) or O(2^n * n) time. The **Travelling Salesman Problem** on n ≤ 20 cities, the **Set Cover** problem, and optimal **task assignment** problems all have bitmask DP solutions that would be impossible without efficient subset enumeration.

