// ── Field Packing: RGBA colour channels ───────────────────────
function packRGBA(r, g, b, a) {
  return ((a & 0xFF) << 24) | ((r & 0xFF) << 16) | ((g & 0xFF) << 8) | (b & 0xFF);
}
function unpackRGBA(color) {
  return {
    a: (color >>> 24) & 0xFF, // >>> unsigned right shift to avoid sign issues
    r: (color >>> 16) & 0xFF,
    g: (color >>>  8) & 0xFF,
    b: (color >>>  0) & 0xFF,
  };
}
const color = packRGBA(0xAA, 0x33, 0x88, 0xFF);
console.log(color.toString(16)); // 'ffaa3388'
console.log(unpackRGBA(color));  // { a:255, r:170, g:51, b:136 }

// ── Subset Enumeration ────────────────────────────────────────
function allSubsets(mask) {
  const result = [];
  // Enumerate all non-empty submasks of 'mask'
  for (let sub = mask; sub > 0; sub = (sub - 1) & mask) {
    result.push(sub.toString(2).padStart(4, '0'));
  }
  result.push('0000'); // empty subset
  return result;
}
// mask = 0b1011 = positions {0, 1, 3}
console.log(allSubsets(0b1011));
// ['1011','1010','1001','1000','0011','0010','0001','0000']
// = all 2^3 = 8 subsets of {0,1,3}

// ── Extract all bit positions set in n ────────────────────────
function getSetBitPositions(n) {
  const positions = [];
  let pos = 0;
  while (n > 0) {
    if (n & 1) positions.push(pos); // test bit 0
    n >>>= 1;                        // unsigned right shift by 1
    pos++;
  }
  return positions;
}
console.log(getSetBitPositions(0b10110)); // [1, 2, 4]

// ── Variable-width field extraction ───────────────────────────
const extract = (n, low, width) => (n >> low) & ((1 << width) - 1);
// Extract 3-bit field starting at bit 4 from 0b10110100
console.log(extract(0b10110100, 4, 3).toString(2)); // '011' = 3
